-- ============================================
-- LUMA — Oz Tome 3 : Chapitres VIII-XII (Le champ de pavots à la mort de la Sorcière)
-- Texte original, domaine public
-- ============================================


with s as (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true),
     lang as (select id from languages where code = 'en')
insert into books (language_id, title, theme, description, cecr_level, cover_emoji, total_pages, position, series_id, volume_number)
select lang.id, 'Tome 3 : La Cité d''Émeraude et la Sorcière', 'Classique • L. Frank Baum (1900)', 'Les compagnons traversent le champ de pavots mortel, rencontrent la Reine des souris des champs, découvrent les quatre visages d''Oz, et affrontent la Méchante Sorcière de l''Ouest jusqu''à sa chute.', 'B1', '💧', 6, 1, s.id, 3
from lang, s;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 1, '[{"en": "They found before them a broad river, flowing swiftly. On the other side they could see the road of yellow brick running through a beautiful country, with green meadows dotted with bright flowers.", "fr": "Ils trouvèrent devant eux une large rivière, coulant rapidement. De l''autre côté ils pouvaient voir la route de briques jaunes traversant un beau pays, avec des prairies vertes parsemées de fleurs éclatantes."}, {"en": "The Tin Woodman took his axe and began to chop down small trees to make a raft. When the Cowardly Lion stepped upon the raft it tipped badly, for he was big and heavy.", "fr": "L''Homme de Fer-Blanc prit sa hache et commença à abattre de petits arbres pour faire un radeau. Quand le Lion Peureux monta sur le radeau, il pencha dangereusement, car il était gros et lourd."}, {"en": "When they reached the middle of the river the swift current swept the raft downstream. The Scarecrow pushed so hard on his long pole that it stuck fast in the mud, and the raft was swept away, leaving him clinging to the pole in the middle of the river.", "fr": "Quand ils atteignirent le milieu de la rivière, le courant rapide emporta le radeau en aval. L''Épouvantail poussa si fort sur sa longue perche qu''elle resta coincée dans la boue, et le radeau fut emporté, le laissant accroché à la perche au milieu de la rivière."}, {"en": "''Something must be done to save us,'' said the Lion. ''I think I can swim to the shore and pull the raft after me, if you will only hold fast to the tip of my tail.'' So he sprang into the water and swam with all his might toward the shore.", "fr": "''Il faut faire quelque chose pour nous sauver,'' dit le Lion. ''Je pense pouvoir nager jusqu''au rivage et tirer le radeau, si vous tenez bien le bout de ma queue.'' Alors il plongea dans l''eau et nagea de toutes ses forces vers le rivage."}, {"en": "A Stork flew by and saw the Scarecrow perched sadly on his pole. ''If he wasn''t so big and heavy I would get him for you,'' remarked the Stork. ''He isn''t heavy a bit,'' said Dorothy, ''for he is stuffed with straw.''", "fr": "Une Cigogne passa et vit l''Épouvantail perché tristement sur sa perche. ''S''il n''était pas si gros et lourd, je vous le ramènerais,'' remarqua la Cigogne. ''Il n''est pas lourd du tout,'' dit Dorothy, ''car il est rembourré de paille.''"}, {"en": "So the big bird flew to the Scarecrow, grabbed him by the arm, and carried him back to the bank. He was so happy that he hugged them all, and sang ''Tol-de-ri-de-oh!'' at every step, he felt so gay.", "fr": "Alors le grand oiseau vola vers l''Épouvantail, l''attrapa par le bras, et le ramena au rivage. Il était si heureux qu''il les serra tous dans ses bras, et chanta ''Tol-de-ri-de-oh !'' à chaque pas, tant il se sentait joyeux."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 2, '[{"en": "They walked along, and soon found themselves in the midst of a great meadow of scarlet poppies. When there are many of these flowers together, their odor is so powerful that anyone who breathes it falls asleep, and if not carried away, sleeps on forever.", "fr": "Ils marchèrent, et se retrouvèrent bientôt au milieu d''une grande prairie de pavots écarlates. Quand il y a beaucoup de ces fleurs ensemble, leur odeur est si puissante que quiconque la respire s''endort, et s''il n''est pas emporté, dort pour toujours."}, {"en": "Dorothy''s eyes grew heavy and she fell among the poppies, fast asleep. Toto had fallen down beside her too. ''If we leave her here she will die,'' said the Lion. ''I myself can scarcely keep my eyes open.''", "fr": "Les yeux de Dorothy devinrent lourds et elle tomba parmi les pavots, profondément endormie. Toto s''était aussi effondré à ses côtés. ''Si on la laisse ici elle mourra,'' dit le Lion. ''Moi-même j''arrive à peine à garder les yeux ouverts.''"}, {"en": "''Run fast,'' said the Scarecrow to the Lion, ''and get out of this deadly flower bed as soon as you can.'' So the Lion aroused himself and bounded forward as fast as he could go, and in a moment was out of sight.", "fr": "''Courez vite,'' dit l''Épouvantail au Lion, ''et sortez de ce lit de fleurs mortel aussi vite que possible.'' Alors le Lion se ressaisit et bondit en avant aussi vite qu''il put, et en un instant disparut."}, {"en": "The Scarecrow and the Tin Woodman, not being made of flesh, were not troubled by the scent. They made a chair with their hands and arms and carried the sleeping girl through the flowers, but soon found their friend the Lion, fast asleep among the poppies too, too heavy to lift.", "fr": "L''Épouvantail et l''Homme de Fer-Blanc, n''étant pas faits de chair, n''étaient pas dérangés par le parfum. Ils firent une chaise avec leurs mains et leurs bras et portèrent la fillette endormie à travers les fleurs, mais trouvèrent bientôt leur ami le Lion, lui aussi profondément endormi parmi les pavots, trop lourd pour être soulevé."}, {"en": "A great yellow Wildcat was chasing a little gray field mouse. The Tin Woodman raised his axe and cut off the Wildcat''s head, saving the mouse''s life.", "fr": "Un grand chat sauvage jaune poursuivait une petite souris des champs grise. L''Homme de Fer-Blanc leva sa hache et coupa la tête du chat sauvage, sauvant la vie de la souris."}, {"en": "''Oh, thank you! Thank you ever so much for saving my life,'' the mouse squeaked. ''Why, I am a Queen—the Queen of all the Field Mice!''", "fr": "''Oh, merci ! Merci infiniment de m''avoir sauvé la vie,'' couina la souris. ''Sachez que je suis une reine—la Reine de toutes les Souris des Champs !''"}]'::jsonb from b;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 3, '[{"en": "The Scarecrow asked if the mice could help save their friend, the Cowardly Lion, asleep in the poppy bed. ''A Lion!'' cried the little Queen. ''Why, he would eat us all up.'' ''Oh, no,'' declared the Scarecrow; ''this Lion is a coward.''", "fr": "L''Épouvantail demanda si les souris pouvaient aider à sauver leur ami, le Lion Peureux, endormi dans le lit de pavots. ''Un Lion !'' s''écria la petite Reine. ''Il nous mangerait tous.'' ''Oh, non,'' déclara l''Épouvantail ; ''ce Lion est un lâche.''"}, {"en": "Thousands of mice came, each bringing a piece of string. The Tin Woodman built a truck from tree limbs, and the mice were harnessed to it to pull the sleeping Lion out of the deadly poppy field.", "fr": "Des milliers de souris vinrent, chacune apportant un bout de ficelle. L''Homme de Fer-Blanc construisit un chariot avec des branches d''arbre, et les souris y furent attelées pour tirer le Lion endormi hors du champ de pavots mortel."}, {"en": "''If ever you need us again,'' said the Queen, ''come out into the field and call, and we shall hear you and come to your assistance. Good-bye!''", "fr": "''Si jamais vous avez encore besoin de nous,'' dit la Reine, ''venez dans le champ et appelez, et nous vous entendrons et viendrons vous aider. Au revoir !''"}, {"en": "At last they reached the great wall that surrounded the Emerald City, high and thick and of a bright green color. There was a bell beside the gate, and Dorothy pushed the button.", "fr": "Ils atteignirent enfin le grand mur qui entourait la Cité d''Émeraude, haut et épais et d''une couleur vert vif. Il y avait une cloche près de la porte, et Dorothy appuya sur le bouton."}, {"en": "A little man clothed all in green appeared. ''We came here to see the Great Oz,'' said Dorothy. ''I am the Guardian of the Gates,'' he said, ''but first you must put on the spectacles, or the brightness of the Emerald City would blind you.''", "fr": "Un petit homme entièrement vêtu de vert apparut. ''Nous sommes venus voir le Grand Oz,'' dit Dorothy. ''Je suis le Gardien des Portes,'' dit-il, ''mais vous devez d''abord mettre les lunettes, sinon l''éclat de la Cité d''Émeraude vous aveuglerait.''"}, {"en": "He fitted spectacles for Dorothy, the Scarecrow, the Tin Woodman, the Lion, and even little Toto, all locked fast with a key around his neck. Then he led them through the gate into the streets of the Emerald City.", "fr": "Il ajusta des lunettes pour Dorothy, l''Épouvantail, l''Homme de Fer-Blanc, le Lion, et même le petit Toto, toutes verrouillées avec une clé autour de son cou. Puis il les guida à travers la porte dans les rues de la Cité d''Émeraude."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 4, '[{"en": "The streets were lined with beautiful houses built of green marble and studded with sparkling emeralds. Everyone seemed happy, contented, and prosperous.", "fr": "Les rues étaient bordées de belles maisons construites en marbre vert et parsemées d''émeraudes scintillantes. Tout le monde semblait heureux, satisfait, et prospère."}, {"en": "A soldier led them to the Palace, where they were told each must enter Oz''s presence alone, one each day. Dorothy went first, and found herself in a big round room where an enormous floating Head spoke to her.", "fr": "Un soldat les mena au Palais, où on leur dit que chacun devait entrer seul en présence d''Oz, un par jour. Dorothy y alla la première, et se retrouva dans une grande salle ronde où une énorme Tête flottante lui parla."}, {"en": "''I am Oz, the Great and Terrible. Kill the Wicked Witch of the West,'' the Head commanded, ''and I will send you back to Kansas—but not before.'' Dorothy began to weep, for she did not know how she could ever do such a thing.", "fr": "''Je suis Oz, le Grand et le Terrible. Tuez la Méchante Sorcière de l''Ouest,'' ordonna la Tête, ''et je vous renverrai au Kansas—mais pas avant.'' Dorothy se mit à pleurer, car elle ne savait pas comment elle pourrait jamais faire une telle chose."}, {"en": "The next day, the Scarecrow entered and found Oz appearing as a lovely winged Lady, who also demanded the Witch''s death before granting him brains.", "fr": "Le lendemain, l''Épouvantail entra et trouva Oz apparaissant comme une adorable Dame ailée, qui exigea aussi la mort de la Sorcière avant de lui accorder de la cervelle."}, {"en": "The Tin Woodman found Oz as a terrible five-eyed Beast, who likewise demanded the Witch''s death before granting a heart. The Lion found Oz as a great Ball of Fire, so hot it singed his whiskers, who demanded the same before granting courage.", "fr": "L''Homme de Fer-Blanc trouva Oz comme une terrible Bête à cinq yeux, qui exigea de même la mort de la Sorcière avant d''accorder un cœur. Le Lion trouva Oz comme une grande Boule de Feu, si chaude qu''elle roussit ses moustaches, qui exigea la même chose avant d''accorder le courage."}, {"en": "''There is only one thing we can do,'' said the Lion, ''and that is to go to the land of the Winkies, seek out the Wicked Witch, and destroy her.'' So they decided to try, though none of them wanted to kill anybody.", "fr": "''Il n''y a qu''une seule chose à faire,'' dit le Lion, ''c''est aller au pays des Winkies, chercher la Méchante Sorcière, et la détruire.'' Alors ils décidèrent d''essayer, même si aucun d''eux ne voulait tuer qui que ce soit."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 5, '[{"en": "''Which road leads to the Wicked Witch of the West?'' asked Dorothy. ''There is no road,'' answered the Guardian of the Gates. ''Keep to the West, where the sun sets, and you cannot fail to find her.''", "fr": "''Quelle route mène à la Méchante Sorcière de l''Ouest ?'' demanda Dorothy. ''Il n''y a pas de route,'' répondit le Gardien des Portes. ''Restez à l''ouest, là où le soleil se couche, et vous ne pourrez pas la manquer.''"}, {"en": "The Wicked Witch had but one eye, yet it was as powerful as a telescope. She saw Dorothy and her friends and blew a silver whistle, sending a pack of great wolves to tear them to pieces. But the Tin Woodman chopped down all forty wolves with his axe.", "fr": "La Méchante Sorcière n''avait qu''un œil, mais il était aussi puissant qu''un télescope. Elle vit Dorothy et ses amis et souffla dans un sifflet d''argent, envoyant une meute de grands loups pour les mettre en pièces. Mais l''Homme de Fer-Blanc abattit les quarante loups avec sa hache."}, {"en": "Furious, the Witch sent a flock of wild crows to peck out their eyes, but the Scarecrow twisted the neck of every single one. Then she sent a swarm of black bees to sting them, but they broke their stings uselessly against the Tin Woodman''s body.", "fr": "Furieuse, la Sorcière envoya une nuée de corbeaux sauvages pour leur crever les yeux, mais l''Épouvantail tordit le cou de chacun d''eux. Puis elle envoya un essaim d''abeilles noires pour les piquer, mais elles brisèrent leurs dards inutilement contre le corps de l''Homme de Fer-Blanc."}, {"en": "Finally the Witch used her last charm—the Golden Cap—summoning the Winged Monkeys. They tore the straw from the Scarecrow, dropped the Tin Woodman onto sharp rocks denting him badly, and tied up the Lion to bring him to the Witch''s castle.", "fr": "Finalement la Sorcière utilisa son dernier charme—le Bonnet d''Or—invoquant les Singes Ailés. Ils arrachèrent la paille de l''Épouvantail, laissèrent tomber l''Homme de Fer-Blanc sur des rochers acérés qui le cabossèrent gravement, et ligotèrent le Lion pour l''amener au château de la Sorcière."}, {"en": "But they dared not harm Dorothy, for they saw the mark of the Good Witch''s kiss upon her forehead. ''We dare not harm this little girl,'' said their leader, ''for she is protected by the Power of Good.''", "fr": "Mais ils n''osèrent pas faire de mal à Dorothy, car ils virent la marque du baiser de la Bonne Sorcière sur son front. ''Nous n''osons pas faire de mal à cette petite fille,'' dit leur chef, ''car elle est protégée par le Pouvoir du Bien.''"}, {"en": "The Witch made Dorothy her slave, forcing her to clean the kitchen. She longed to steal Dorothy''s Silver Shoes, and tricked her with an invisible iron bar, causing her to trip and lose one shoe, which the Witch snatched and put on her own foot.", "fr": "La Sorcière fit de Dorothy son esclave, la forçant à nettoyer la cuisine. Elle rêvait de voler les Souliers d''Argent de Dorothy, et la piégea avec une barre de fer invisible, la faisant trébucher et perdre un soulier, que la Sorcière saisit et mit à son propre pied."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 3 : La Cité d''Émeraude et la Sorcière' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 6, '[{"en": "''Give me back my shoe!'' cried Dorothy angrily. ''I will not,'' retorted the Witch, laughing, ''for it is now my shoe.'' This made Dorothy so angry that she picked up a bucket of water and dashed it over the Witch, wetting her from head to foot.", "fr": "''Rendez-moi mon soulier !'' s''écria Dorothy avec colère. ''Je ne le ferai pas,'' rétorqua la Sorcière en riant, ''car c''est maintenant mon soulier.'' Cela mit Dorothy si en colère qu''elle prit un seau d''eau et le lui jeta dessus, la trempant de la tête aux pieds."}, {"en": "''See what you have done! In a minute I shall melt away,'' the Witch screamed. With these words she fell down in a brown, melted, shapeless mass and began to spread over the kitchen floor.", "fr": "''Regardez ce que vous avez fait ! Dans une minute je vais fondre,'' hurla la Sorcière. Sur ces mots elle s''effondra en une masse brune, fondue, informe, et commença à se répandre sur le sol de la cuisine."}, {"en": "''I have been wicked in my day, but I never thought a little girl like you would ever be able to melt me,'' the Witch wailed. Dorothy swept it all out the door, picked up the silver shoe, and ran to tell the Lion they were prisoners no longer.", "fr": "''J''ai été méchante en mon temps, mais je n''aurais jamais pensé qu''une petite fille comme vous pourrait un jour me faire fondre,'' gémit la Sorcière. Dorothy balaya le tout par la porte, ramassa le soulier d''argent, et courut annoncer au Lion qu''ils n''étaient plus prisonniers."}]'::jsonb from b;
